-- ==============================================================================
-- Flyway Database Migration: V3__comprehensive_medical_catalogs.sql
-- Description: Comprehensive Medical Catalogs (ICD-10-CM, LOINC, CPT, SNOMED-CT, Formulary)
-- ==============================================================================

-- 1. EXTENDED ICD-10-CM DIAGNOSTIC CATALOG
ON CONFLICT (code) DO UPDATE 
SET description = EXCLUDED.description,
    chapter = EXCLUDED.chapter,
    is_chronic = EXCLUDED.is_chronic,
    is_notifiable = EXCLUDED.is_notifiable,
    updated_at = NOW();

-- 2. EXTENDED SURGICAL CPT PRICE LIST CATALOG
ON CONFLICT (code) DO UPDATE 
SET name = EXCLUDED.name,
    category = EXCLUDED.category,
    standard_rate = EXCLUDED.standard_rate,
    tax_rate = EXCLUDED.tax_rate,
    updated_at = NOW();
